<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thanh toán — Fieldcraft</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;700;800&family=Oswald:wght@500;600&display=swap" rel="stylesheet"><style>body{margin:0;background:#f5f7f1;color:#07110d;font:500 14px Manrope,sans-serif}.wrap{max-width:1000px;margin:auto;padding:40px 22px}.brand{font:600 28px Oswald,sans-serif}.brand i{display:inline-block;width:20px;height:20px;margin-right:7px;background:#caff39;border-radius:2px 10px 2px 10px;transform:rotate(-20deg)}h1{font:600 42px/.95 Oswald,sans-serif;text-transform:uppercase;margin:38px 0 20px}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:20px}.panel{background:white;border:1px solid #dce3da;border-radius:8px;padding:22px}.field{display:block;font-size:10px;font-weight:800;margin:0 0 15px}.field input{box-sizing:border-box;width:100%;padding:11px;margin-top:6px;border:1px solid #dce3da;border-radius:4px}.pay{display:flex;gap:10px;margin:12px 0}.pay label{border:1px solid #dce3da;border-radius:4px;padding:10px;flex:1;font-size:11px}.item{display:flex;gap:10px;margin:12px 0;font-size:11px}.item img{width:48px;height:48px;object-fit:cover;background:#eef2ec;border-radius:4px}.total{border-top:1px solid #dce3da;margin-top:18px;padding-top:14px;display:flex;justify-content:space-between;font:700 17px Manrope}.btn{width:100%;border:0;border-radius:4px;padding:14px;background:#caff39;font-weight:800;margin-top:20px;cursor:pointer}.muted{color:#718078;font-size:11px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="brand" href="{{ route('store.home') }}"><i></i>FIELDCRAFT</a><h1>Thanh toán</h1><form method="POST" action="{{ route('checkout.store') }}" class="grid">@csrf<div class="panel"><label class="field">HỌ VÀ TÊN<input name="name" required value="{{ old('name') }}"></label><label class="field">SỐ ĐIỆN THOẠI<input name="phone" required value="{{ old('phone') }}"></label><label class="field">ĐỊA CHỈ GIAO HÀNG<input name="address" required value="{{ old('address') }}" placeholder="Số nhà, đường, phường/xã, tỉnh/thành"></label><label class="field">MÃ GIẢM GIÁ<input name="coupon" value="{{ old('coupon') }}" placeholder="MESSI10"></label><b style="font-size:11px">PHƯƠNG THỨC THANH TOÁN</b><div class="pay"><label><input type="radio" name="payment_method" value="cod" checked> COD</label><label><input type="radio" name="payment_method" value="online"> Online (demo)</label></div><button class="btn">CHỐT ĐƠN HÀNG →</button></div><aside class="panel"><b>ĐƠN HÀNG CỦA BẠN</b>@php($total=0)@foreach($items as $line)@php($total += $line['variant']->price*$line['quantity'])<div class="item"><img src="{{ $line['variant']->product->images->first()?->path }}"><div><b>{{ $line['variant']->product->name }}</b><div class="muted">{{ $line['variant']->color }} / Size {{ $line['variant']->size }} × {{ $line['quantity'] }}</div><div>{{ number_format($line['variant']->price*$line['quantity'],0,',','.') }}₫</div></div></div>@endforeach<div class="total"><span>TỔNG</span><span>{{ number_format($total,0,',','.') }}₫</span></div></aside></form></main></body></html>
